export const getJackpotRunResponseTwoEntriesItemPositionMax = 17;

export const getJackpotRunResponseTwoEntriesItemHomeWinProbabilityMin = 0;
export const getJackpotRunResponseTwoEntriesItemHomeWinProbabilityMax = 100;

export const getJackpotRunResponseTwoEntriesItemDrawProbabilityMin = 0;
export const getJackpotRunResponseTwoEntriesItemDrawProbabilityMax = 100;

export const getJackpotRunResponseTwoEntriesItemAwayWinProbabilityMin = 0;
export const getJackpotRunResponseTwoEntriesItemAwayWinProbabilityMax = 100;

export const getJackpotRunResponseTwoEntriesItemConfidenceMin = 0;
export const getJackpotRunResponseTwoEntriesItemConfidenceMax = 100;

export const getJackpotRunResponseTwoEntriesItemDifficultyScoreMin = 0;
export const getJackpotRunResponseTwoEntriesItemDifficultyScoreMax = 100;

export const getJackpotRunResponseTwoEntriesItemUpsetRiskScoreMin = 0;
export const getJackpotRunResponseTwoEntriesItemUpsetRiskScoreMax = 100;

export const getJackpotRunResponseTwoEntriesItemHeadToHeadMatchCountMin = 0;

export const getJackpotRunResponseTwoEntriesMin = 17;
export const getJackpotRunResponseTwoEntriesMax = 17;



export const GetJackpotRunResponse = zod.object({
  "id": zod.number().int(),
  "createdAt": zod.coerce.date(),
  "riskProfile": zod.enum(['safe', 'higher-risk']),
  "fixtureCount": zod.literal(17),
  "completedFixtures": zod.number().int().min(getJackpotRunResponseOneCompletedFixturesMin).max(getJackpotRunResponseOneCompletedFixturesMax),
  "correctSelections": zod.number().int().min(getJackpotRunResponseOneCorrectSelectionsMin).max(getJackpotRunResponseOneCorrectSelectionsMax),
  "perfect": zod.boolean().nullable()
}).and(zod.object({
  "entries": zod.array(zod.object({
  "position": zod.number().int().min(1).max(getJackpotRunResponseTwoEntriesItemPositionMax),
  "fixture": zod.object({
  "id": zod.number().int(),
  "providerMatchId": zod.number().int().nullable(),
  "competitionCode": zod.string().nullable(),
  "competitionName": zod.string().nullable(),
  "competitionType": zod.string().nullable(),
  "homeTeamId": zod.number().int().nullable(),
  "homeTeamName": zod.string(),
  "awayTeamId": zod.number().int().nullable(),
  "awayTeamName": zod.string(),
  "kickoffAt": zod.coerce.date().nullable(),
  "status": zod.string(),
  "finalHomeGoals": zod.number().int().nullable(),
  "finalAwayGoals": zod.number().int().nullable()
}),
  "homeWinProbability": zod.number().min(getJackpotRunResponseTwoEntriesItemHomeWinProbabilityMin).max(getJackpotRunResponseTwoEntriesItemHomeWinProbabilityMax),
  "drawProbability": zod.number().min(getJackpotRunResponseTwoEntriesItemDrawProbabilityMin).max(getJackpotRunResponseTwoEntriesItemDrawProbabilityMax),
  "awayWinProbability": zod.number().min(getJackpotRunResponseTwoEntriesItemAwayWinProbabilityMin).max(getJackpotRunResponseTwoEntriesItemAwayWinProbabilityMax),
  "safestSelection": zod.enum(['HOME', 'DRAW', 'AWAY']),
  "higherRiskAlternative": zod.enum(['HOME', 'DRAW', 'AWAY']),
  "selectedSelection": zod.enum(['HOME', 'DRAW', 'AWAY']),
  "confidence": zod.number().min(getJackpotRunResponseTwoEntriesItemConfidenceMin).max(getJackpotRunResponseTwoEntriesItemConfidenceMax),
  "difficultyScore": zod.number().min(getJackpotRunResponseTwoEntriesItemDifficultyScoreMin).max(getJackpotRunResponseTwoEntriesItemDifficultyScoreMax),
  "upsetRiskScore": zod.number().min(getJackpotRunResponseTwoEntriesItemUpsetRiskScoreMin).max(getJackpotRunResponseTwoEntriesItemUpsetRiskScoreMax),
  "upsetRisk": zod.enum(['low', 'medium', 'high']),
  "headToHeadMatchCount": zod.number().int().min(getJackpotRunResponseTwoEntriesItemHeadToHeadMatchCountMin),
  "headToHeadUsed": zod.boolean()
})).min(getJackpotRunResponseTwoEntriesMin).max(getJackpotRunResponseTwoEntriesMax),
  "disclaimer": zod.string()
}))


